                                if (typeof info.zhen_jiashangxian != 'number') info.zhen_jiashangxian = 0;
                                info.zhen_jiashangxian += num;
                                if (info.zhen_jiashangxian == 0) player.unmarkSkill('zhen_jiashangxian');
                                else player.markSkill('zhen_jiashangxian');
