                                if (!event.player.isMinHandcard() && !event.player.isMinEquip() && !event.player.isMinHp() && get.attitude(player, event.player) <= 0) return true;
                                if (event.player.isMinHandcard() && event.player.isMinEquip() && event.player.isMinHp() && get.attitude(player, event.player) > 0) return true;
                                if (!event.player.isMaxHandcard() && !event.player.isMaxEquip() && !event.player.isMaxHp() && get.attitude(player, event.player) > 0) return true;
                                if (player.hp == 1 && (!player.countCards('h', 'tao') || !player.countCards('h', 'jiu'))) return false;
